var EXTRA=[{"dot": "gray", "pmid": "43003363", "h": "Revisione di protesi per infezione contro allentamento asettico: a lunghissimo termine la settica dura meno", "v": "Coorte retrospettiva di un solo chirurgo a Seul, con controllo molto lungo: dopo revisione per infezione più re-revisioni, più reinfezioni e punteggi più bassi. Stesso gruppo della scheda di ieri sull'allineamento; non randomizzato.", "temi": ["protesi totale", "revisione", "infezione"], "doi": "10.1016/j.arth.2026.10.053", "j": "J Arthroplasty"}, {"dot": "gray", "pmid": "43008904", "h": "Radiografie di routine dopo protesi non complicata: quasi mai cambiano la gestione", "v": "Revisione sistematica con meta-analisi su anca e ginocchio: i rari cambi di gestione stanno tutti nell'anca, nessuno negli studi sul ginocchio; gli eventi sono così rari che la differenza fra le due articolazioni resta un'ipotesi.", "temi": ["protesi totale", "radiografie", "costi"], "doi": "10.1016/j.arth.2026.11.033", "j": "J Arthroplasty"}, {"dot": "gray", "pmid": "43008084", "h": "Artrite settica del ginocchio nativo: il lavaggio chirurgico tardivo si associa a più reinterventi e mortalità", "v": "Banca dati dei ricoveri della Florida, analisi pesata per propensity score: nel ginocchio il ritardo oltre il primo giorno di ricovero si associa a esiti peggiori, nell'anca no. Retrospettivo amministrativo, senza dati su aspirazione e antibiotici.", "temi": ["artrite settica", "ginocchio nativo", "tempistica"], "doi": "10.1097/CORR.0000000000004199", "j": "Clin Orthop Relat Res"}, {"dot": "gray", "pmid": "43005490", "h": "Osteotomia tibiale d'apertura con guide su misura e sutura della radice meniscale mediale", "v": "Video tecnico: le guide su misura costruite sulla TC permettono di pianificare il tunnel della radice e la fissazione dell'osteotomia senza conflitto fra i due; nessun dato su pazienti.", "temi": ["osteotomia", "radice meniscale", "guide su misura"], "doi": "10.1177/26350254261466712", "j": "Video J Sports Med"}, {"dot": "gray", "pmid": "43005337", "h": "LCA carente: un tutore adattivo riduce valgo e rotazione nei salti rispetto a uno passivo", "v": "Studio di laboratorio su pochi uomini con LCA carente, solo cinematica, senza esiti clinici né confronto con la ricostruzione: un'ipotesi per la riabilitazione, non un'indicazione.", "temi": ["LCA", "tutore", "biomeccanica"], "doi": "10.1002/ars2.70133", "j": "Arthrosc Sports Med Rehabil"}, {"dot": "gray", "pmid": "43002387", "h": "Elettrostimolazione del quadricipite dopo LCA: paziente giusto, dose giusta, momento giusto", "v": "Commento editoriale: l'uso precoce è sostenuto quando il deficit di attivazione è marcato, ma la durata va guidata dalla risoluzione del deficit e non dal calendario. Opinione, non dato primario.", "temi": ["LCA", "quadricipite", "riabilitazione"], "doi": "10.1002/arj.70746", "j": "Arthroscopy"}, {"dot": "gray", "pmid": "43001024", "h": "Antinfiammatori per il dolore cronico di ginocchio: eventi avversi più frequenti per bocca che sulla pelle", "v": "Revisione sistematica con meta-analisi di studi randomizzati: eventi soprattutto gastrointestinali per bocca e cutanei per via topica; eventi gravi troppo rari per una stima affidabile, certezza bassa o molto bassa.", "temi": ["artrosi", "antinfiammatori", "sicurezza"], "doi": "10.1080/17581869.2026.2754352", "j": "Pain Manag"}, {"dot": "gray", "pmid": "43009345", "h": "Protesi monocompartimentale mediale: soddisfazione e beneficio funzionale non coincidono sempre", "v": "Coorte retrospettiva monocentrica di anziani: convinzioni sulla salute e capacità di autogestione prima dell'intervento si associano all'insoddisfazione anche a parità di beneficio. Osservazionale, da validare prima di usarlo nelle decisioni.", "temi": ["protesi monocompartimentale", "soddisfazione", "esiti riferiti dal paziente"], "doi": "10.1016/j.surge.2026.10.013", "j": "Surgeon"}, {"dot": "gray", "pmid": "43003366", "h": "Protesi totale: l'angolo ischiocrurali-popliteo in anestesia si associa all'estensione dopo un anno", "v": "Studio retrospettivo monocentrico su ginocchia vare con protesi posterostabilizzata: la tensione dei tessuti posteriori fuori dall'articolazione aggiunge informazione sul recupero dell'estensione. Associazione, nessun intervento testato.", "temi": ["protesi totale", "estensione", "flessum"], "doi": "10.1016/j.arth.2026.11.024", "j": "J Arthroplasty"}, {"dot": "gray", "pmid": "43000271", "h": "Protesi totale: i casi operati più tardi nella giornata si associano a più infezioni", "v": "Coorte retrospettiva di un solo ospedale con più chirurghi: l'ordine in sala si associa a infezione periprotesica, tempo operatorio e degenza. Gli autori stessi la definiscono un'associazione esplorativa.", "temi": ["protesi totale", "infezione periprotesica", "organizzazione"], "doi": "10.1186/s12893-026-04117-2", "j": "BMC Surg"}, {"dot": "gray", "pmid": "43006808", "h": "Carichi sulla protesi nella corsa, nei salti e nei cambi di direzione: un esplorativo di laboratorio", "v": "Modellazione muscolo-scheletrica su pochissimi pazienti con protesi di ginocchio, in maggioranza protesi d'anca: utile come ipotesi sul ritorno allo sport, non come soglia per consigliarlo.", "temi": ["protesi", "ritorno allo sport", "biomeccanica"], "doi": "10.2519/josptopen.2026.0238", "j": "JOSPT Open"}, {"dot": "gray", "pmid": "42996763", "h": "LCA: il bottone di estensione passato dentro l'articolazione, senza seconda incisione", "v": "Nota tecnica per salvare una fissazione corticale femorale compromessa durante l'intervento; nessun dato su pazienti né confronto con la via classica.", "temi": ["LCA", "fissazione femorale", "tecnica chirurgica"], "doi": "10.1002/atn2.70371", "j": "Arthrosc Tech"}];
var SCOPERTE=[{"pmid": "43004996", "t": "Giappone: l'osteotomia valgizzante del condilo tibiale unita all'osteotomia a V rovesciata per il varo grave", "v": "Dalla scuola giapponese (Hyogo, Sapporo, Hokkaido) una tecnica che corregge insieme la deformità ossea e quella intra-articolare, alzando il piatto mediale, e riduce l'apertura del cuneo rispetto all'osteotomia d'apertura classica. Nota tecnica senza esiti: vale per come ragiona sull'obliquità della linea articolare.", "temi": ["osteotomia", "Giappone", "obliquità della linea articolare"], "doi": "10.1002/atn2.70361"}, {"pmid": "43005297", "t": "India: ricostruzione del LCA a tre fasci, con tre tunnel femorali e tre tibiali", "v": "Da Thiruvananthapuram, una tecnica a tre fasci con ischiocrurali che, secondo gli autori, alcuni centri in Giappone e in India adottano per ridurre le rotture. Nota tecnica senza dati: interessa come idea anatomica lontana dalla tua, non come proposta.", "temi": ["LCA", "India", "tecnica a tre fasci"], "doi": "10.1002/atn2.70328"}, {"pmid": "43008325", "t": "Reti neurali per stimare rigidità e pre-tensione dei legamenti del ginocchio dai test di lassità", "v": "Da Aalborg: modelli addestrati su ginocchia virtuali stimano i parametri di crociati e collaterali in tempi rapidi, al posto dell'ottimizzazione classica. Solo dati sintetici, nessuna validazione sperimentale: un ponte possibile fra la lassità che il robot misura e il modello del singolo paziente.", "temi": ["intelligenza artificiale", "legamenti", "modellazione"], "doi": "10.1088/1873-4030/aec016"}];
var SOC={"1": {"video": "Protesi di ginocchio in età lavorativa: uno studio randomizzato olandese in undici centri, 287 pazienti.\n\nUn programma digitale personalizzato, con sensore di attività, consigli e obiettivi scelti dal paziente, ha portato a riprendere le attività desiderate in una mediana di 52 giorni contro 75 con le cure abituali (hazard ratio 1,6; 1,3-2,0).\n\nIl limite: il paziente sa di essere seguito, e lo studio non dice quale parte del programma conti. Per il proprio caso decide il chirurgo.\nFonte: PubMed, PMID 43008926.", "linkedin": "Ritorno alle attività dopo protesi di ginocchio: RCT multicentrico ACTIVE (Osteoarthritis and Cartilage, 2026).\n\n287 pazienti in età lavorativa, protesi totale o monocompartimentale: tempo mediano alla ripresa delle attività scelte 52 giorni [32-84] con il programma eHealth personalizzato contro 75 [36-137] con le cure abituali; HR 1,6 (1,3-2,0).\n\nIl limite: intervento comportamentale non in cieco, esito riferito, componenti non separabili; esiti secondari non nell'abstract.\nFonte: PubMed, PMID 43008926.", "instagram": "Protesi di ginocchio e ritorno alla vita di tutti i giorni.\n\nUno studio randomizzato: con un programma digitale personalizzato, le attività scelte dal paziente sono riprese in una mediana di 52 giorni contro 75.\n\nIl paziente sapeva di essere seguito: è un limite. PMID 43008926.", "pazienti": "Protesi di ginocchio: quanto tempo per tornare alle proprie attività?\n\nUno studio olandese ha assegnato per sorteggio 287 persone ancora al lavoro a un programma digitale personalizzato, con un contapassi e consigli sulle attività scelte da ciascuno, oppure alle cure abituali. Con il programma, le attività desiderate sono riprese in una mediana di 52 giorni invece di 75.\n\nIl limite: chi partecipa sa di essere seguito, e il programma non è uguale ovunque. Per il proprio caso decide il chirurgo.\nFonte: PubMed, PMID 43008926."}};
var SOCV={"1": {"video": {"chir": ["Studio ACTIVE, Osteoarthritis and Cartilage 2026: uno studio randomizzato controllato multicentrico in singolo cieco, undici centri olandesi, sul ritorno alle attività quotidiane dopo protesi di ginocchio. Sono entrati duecentottantasette pazienti in età lavorativa, occupati almeno otto ore a settimana, candidati a protesi totale o monocompartimentale primaria. L'intervento è un programma eHealth personalizzato con sensore di attività, un colloquio con un case manager e obiettivi scelti dal paziente; il controllo sono le cure abituali.", "L'esito primario è il tempo alla ripresa delle attività scelte, misurato con il PROMIS-PF. La mediana è cinquantadue giorni nel gruppo intervento contro settantacinque nel controllo, con un hazard ratio di uno virgola sei e un intervallo da uno virgola tre a due virgola zero. In termini pratici, una mediana di ventitré giorni in meno, con età e quota di donne simili nei due bracci.", "Il limite: è un intervento comportamentale, quindi il paziente non è in cieco e l'esito è riferito; il pacchetto unisce sensore, consigli, case manager e obiettivi, e lo studio non dice quale componente produca l'effetto. Ritorno al lavoro, sport, complicanze e punteggi del ginocchio non sono riportati nell'abstract. Il dato utile è il principio: una guida strutturata e personalizzata sul ritorno alle attività accorcia i tempi.\nFonte: PubMed, PMID 43008926."], "misto": ["Dopo una protesi di ginocchio, quando si torna alle proprie attività? Uno studio olandese pubblicato nel 2026 ha coinvolto undici ospedali e duecentottantasette persone ancora al lavoro, operate di protesi totale o parziale. Metà, per sorteggio, ha seguito un programma digitale personalizzato, con un contapassi, consigli su misura e un colloquio con un coordinatore; l'altra metà ha ricevuto le cure abituali, che comprendevano già una parte digitale.", "Il risultato principale è il tempo per riprendere le attività che ciascuno aveva scelto, dal lavoro al giardinaggio. Con il programma la mediana è stata di cinquantadue giorni, con le cure abituali di settantacinque: circa tre settimane in meno. La differenza è statisticamente solida, con un intervallo che resta lontano dall'assenza di effetto, ed età e sesso erano simili nei due gruppi.", "Il limite: chi partecipa sa di essere seguito più da vicino, e il programma mette insieme più strumenti, quindi non si sa quale conti davvero. Lo studio non riporta, nell'abstract, il ritorno al lavoro, le complicanze né i punteggi del ginocchio. Il messaggio pratico è che fissare obiettivi chiari e personali aiuta il recupero; il percorso concreto si decide con il proprio chirurgo e il fisioterapista.\nFonte: PubMed, PMID 43008926."], "pazienti": ["Dopo una protesi di ginocchio, quanto tempo serve per tornare alle proprie attività? Uno studio fatto in undici ospedali olandesi ha seguito duecentottantasette persone che lavoravano ancora. Per sorteggio, una parte ha usato un programma sul telefono e un contapassi, con consigli su misura e obiettivi scelti da ciascuno; l'altra parte ha seguito il percorso abituale dell'ospedale.", "Con il programma, le persone hanno ripreso le attività che avevano scelto in una mediana di cinquantadue giorni; con il percorso abituale in settantacinque giorni. Vuol dire circa tre settimane prima, per esempio per tornare al lavoro, a fare la spesa a piedi o a un hobby. I due gruppi avevano un'età e una composizione simili, quindi il confronto è equo.", "Il limite: chi usa il programma sa di essere seguito di più, e questo può contare da solo; inoltre non si sa quale parte del programma aiuti davvero. Lo studio non dice, nel riassunto, nulla su complicanze o dolore. Il consiglio che se ne ricava è semplice: parlare prima dell'intervento di quali attività si vogliono riprendere. Per il proprio caso decide il chirurgo.\nFonte: PubMed, PMID 43008926."]}, "linkedin": {"chir": ["Ritorno alle attività dopo protesi di ginocchio: RCT ACTIVE (Osteoarthritis and Cartilage, 2026)", "Studio randomizzato multicentrico in singolo cieco, 11 centri olandesi, 287 pazienti in età lavorativa con protesi totale o monocompartimentale. Programma eHealth personalizzato (sensore di attività, case manager, goal attainment scaling) contro cure abituali: tempo mediano alla ripresa delle attività scelte 52 giorni [32-84] contro 75 [36-137]; HR 1,6 (1,3-2,0).", "Il limite: intervento comportamentale non in cieco per il paziente, esito riferito, componenti non separabili; ritorno al lavoro e sicurezza non nell'abstract.\nFonte: PubMed, PMID 43008926."], "misto": ["Protesi di ginocchio: un programma digitale personalizzato accorcia di circa tre settimane il ritorno alle attività", "Uno studio randomizzato in 11 ospedali olandesi, con 287 persone ancora al lavoro, ha confrontato un programma digitale con contapassi, consigli su misura e obiettivi personali con le cure abituali. Le attività scelte sono riprese in una mediana di 52 giorni contro 75, con una differenza statisticamente solida (hazard ratio 1,6; intervallo 1,3-2,0).", "Il limite: chi partecipa sa di essere seguito, e il programma mette insieme più strumenti di cui non si sa quale conti.\nFonte: PubMed, PMID 43008926."], "pazienti": ["Protesi di ginocchio: con obiettivi chiari e personali si torna prima alle proprie attività", "In uno studio olandese, 287 persone che lavoravano ancora sono state assegnate per sorteggio a un programma sul telefono con contapassi e consigli su misura, oppure al percorso abituale. Con il programma, le attività scelte da ciascuno sono riprese in una mediana di 52 giorni invece di 75.", "Il limite: chi usa il programma sa di essere seguito di più. Per il proprio caso decide il chirurgo.\nFonte: PubMed, PMID 43008926."]}, "instagram": {"chir": ["RCT ACTIVE: ritorno alle attività dopo protesi.", "287 pazienti, 11 centri. Programma eHealth personalizzato: mediana 52 contro 75 giorni, HR 1,6 (1,3-2,0).", "Non in cieco per il paziente. PMID 43008926."], "misto": ["Protesi di ginocchio: tornare prima alle proprie attività.", "Studio randomizzato su 287 persone al lavoro: con un programma digitale personalizzato, mediana di 52 giorni contro 75.", "Il limite: chi partecipa sa di essere seguito. PMID 43008926."], "pazienti": ["Dopo la protesi di ginocchio, quanto ci vuole?", "In uno studio con 287 persone, chi aveva un programma su misura sul telefono è tornato alle sue attività in 52 giorni invece di 75.", "Ogni caso è diverso: decide il chirurgo. PMID 43008926."]}, "reel": {"chir": ["Protesi e ritorno alle attività.", "RCT: 52 contro 75 giorni.", "Paziente non in cieco."], "misto": ["Dopo la protesi di ginocchio.", "Programma su misura: tre settimane prima.", "Chi partecipa sa di essere seguito."], "pazienti": ["Protesi e vita di tutti i giorni.", "Obiettivi chiari, ritorno più rapido.", "Decide il chirurgo."]}}};
var TAGS={"1": {"linkedin": "#Ortopedia #ProtesiDiGinocchio #Riabilitazione", "instagram": "#ortopedia #ginocchio #protesidiginocchio #riabilitazione #ritornoallavoro #artrosi #medicinabasatasulleprove #chirurgiadelginocchio #ortopediaticino #ticino", "kw": "protesi di ginocchio, ritorno alle attività dopo protesi, riabilitazione dopo protesi di ginocchio, protesi monocompartimentale, ticino"}};
var NLB={"1": {"prof": ["Protesi di ginocchio in età lavorativa: in un RCT un programma eHealth anticipa di 23 giorni il ritorno alle attività", "RCT multicentrico in singolo cieco (Osteoarthritis and Cartilage, 2026; solo abstract): 287 pazienti in età lavorativa con protesi totale o monocompartimentale; tempo mediano alla ripresa delle attività scelte 52 giorni [32-84] con il programma personalizzato contro 75 [36-137] con le cure abituali, HR 1,6 (1,3-2,0).", "Nota critica: intervento comportamentale non mascherabile, esito riferito dal paziente e pacchetto a più componenti; ritorno al lavoro, complicanze e punteggi del ginocchio non sono riportati nell'abstract."], "mix": ["Protesi di ginocchio: un programma digitale personalizzato accorcia di circa tre settimane il ritorno alle attività", "Uno studio randomizzato in undici ospedali olandesi ha seguito 287 persone ancora al lavoro dopo una protesi totale o parziale di ginocchio. Con un programma digitale che univa contapassi, consigli su misura, un colloquio con un coordinatore e obiettivi personali, le attività scelte sono riprese in una mediana di 52 giorni, contro 75 con le cure abituali.", "Nota sul limite: chi partecipa sa di essere seguito più da vicino e il programma mette insieme più strumenti, quindi non si sa quale conti; lo studio non riporta, nel riassunto, complicanze né dolore."], "paz": ["Protesi di ginocchio: obiettivi chiari e personali aiutano a tornare prima alle proprie attività", "In uno studio olandese, 287 persone che lavoravano ancora sono state assegnate per sorteggio a un programma sul telefono con contapassi e consigli su misura, oppure al percorso abituale. Con il programma, le attività che ciascuno aveva scelto sono riprese in circa cinquanta giorni invece di settantacinque.", "Nota rassicurante: entrambi i gruppi hanno ripreso le loro attività; il programma ha solo accorciato i tempi, e il percorso giusto per ciascuno si decide con il proprio chirurgo."], "kw": "protesi di ginocchio, ritorno alle attività dopo protesi, riabilitazione dopo protesi, protesi monocompartimentale"}, "2": {"prof": ["Allotrapianto osteocondrale: l'asse preoperatorio non predice esiti né reinterventi, ma i deviati erano stati riallineati", "Serie di casi di livello IV (Am J Sports Med, 2026; solo abstract): 66 pazienti con controllo minimo di 2 anni; nessuna misura di asse associata a MCID, PASS, SCB o reintervento (p > 0,05). Reinterventi 37,9%, sopravvivenza dell'innesto 93,9%; con HKA oltre 5°, reinterventi 43,8% contro 36,0% (p = 0,768).", "Nota critica: 13 dei 16 pazienti deviati avevano un riallineamento associato, quindi lo studio misura l'asse corretto e non quello lasciato; con 4 fallimenti non ha potenza sulla sopravvivenza."], "mix": ["Trapianto di cartilagine e osso da donatore: l'asse della gamba corretto insieme non peggiora i risultati", "Uno studio di Chicago su 66 pazienti operati con un trapianto osteocondrale da donatore, seguiti per almeno due anni, non ha trovato un legame fra l'asse della gamba prima dell'intervento e il miglioramento percepito dai pazienti o la necessità di un nuovo intervento. Il trapianto era ancora in sede nel 93,9% dei casi, mentre il 37,9% ha avuto un secondo intervento di qualche tipo.", "Nota sul limite: quasi tutti i pazienti con l'asse molto deviato avevano avuto anche una correzione dell'asse; lo studio non dice che cosa succede se l'asse non si corregge."], "paz": ["Trapianto di cartilagine nel ginocchio: correggere l'asse della gamba fa parte del trattamento", "Uno studio americano su 66 pazienti con un trapianto di cartilagine e osso da donatore ha visto che, quando l'asse della gamba molto storta veniva corretto nello stesso intervento, i risultati erano simili a quelli dei pazienti con la gamba dritta. Nella grande maggioranza dei casi il trapianto era ancora al suo posto dopo almeno due anni.", "Nota rassicurante: lo studio conferma che valutare l'asse della gamba fa parte della cura; le scelte per il proprio ginocchio si fanno con il chirurgo."], "kw": "trapianto di cartilagine ginocchio, allotrapianto osteocondrale, osteotomia, lesione cartilaginea"}, "3": {"prof": ["Infiltrazioni nel ginocchio fra 40 e 60 anni: ogni iniezione si associa a un rischio di protesi più alto del 12%", "Coorte di popolazione (Bone Joint Open, 2026; solo abstract): 1.897 pazienti, 2.336 ginocchia, 8.600 iniezioni; protesi nel 39,3%. HR 1,12 per iniezione (IC 95% 1,08-1,17) aggiustato per età, IMC e grado KL; nell'artrosi iniziale corticosteroide HR 1,27 (IC 95% 1,17-1,37).", "Nota critica: confondimento per indicazione, perché chi ha più sintomi riceve più iniezioni e arriva più spesso alla protesi; dolore e funzione non sono fra le covariate."], "mix": ["Infiltrazioni nel ginocchio fra 40 e 60 anni: più iniezioni si associano a una protesi più frequente", "Uno studio della Mayo Clinic su quasi 1.900 persone fra 40 e 60 anni, che hanno ricevuto in tutto 8.600 infiltrazioni di cortisone o acido ialuronico, ha visto che ogni iniezione in più si associava a una probabilità di protesi più alta del 12%. Nell'artrosi iniziale, il cortisone si associava a un aumento del 27%.", "Nota sul limite: chi ha più dolore riceve più iniezioni e arriva più spesso alla protesi; lo studio mostra un'associazione e non prova che sia l'iniezione a far progredire l'artrosi."], "paz": ["Infiltrazioni nel ginocchio: che cosa dice un grande studio americano sul rischio di protesi", "Uno studio su quasi 1.900 persone fra 40 e 60 anni ha visto che chi riceve più infiltrazioni nel ginocchio arriva più spesso alla protesi. Non è detto che sia l'infiltrazione la causa: chi ha più dolore ne riceve di più, e il dolore stesso porta più spesso all'intervento.", "Nota rassicurante: le infiltrazioni restano una delle possibilità per alleviare il dolore; quante farne e quando si decide con il proprio medico."], "kw": "infiltrazioni ginocchio, cortisone ginocchio, acido ialuronico, artrosi del ginocchio"}, "4": {"prof": ["Radice posteriore del menisco laterale con LCA rotto: punteggi migliori con la riparazione, nessun beneficio dimostrato sull'innesto", "Revisione narrativa (J ISAKOS, 2026; solo abstract): frequenza 7,1-12,2% nelle ricostruzioni primarie e fino al 40,7% in revisioni selezionate, con definizioni diverse; associazioni ricorrenti con trauma da contatto, lesione meniscale mediale e slope tibiale laterale aumentato. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.", "Nota critica: revisione narrativa senza metodo sistematico dichiarato; le classificazioni sono descrittive e gli autori stessi scrivono che un miglioramento della sopravvivenza dell'innesto non è dimostrato."], "mix": ["Lesione della radice del menisco laterale insieme alla rottura del crociato: che cosa si sa oggi", "Una revisione del 2026 riassume gli studi su una lesione del menisco laterale vicino alla sua inserzione posteriore, presente in una quota di ginocchia con rottura del legamento crociato anteriore e più frequente nelle revisioni. La risonanza da sola può non vederla, e l'esame in artroscopia resta decisivo; ripararla insieme al crociato si associa a punteggi migliori.", "Nota sul limite: è una revisione non sistematica di studi di basso livello, e non è dimostrato che riparare la radice protegga il nuovo legamento."], "paz": ["Menisco e crociato: una lesione nascosta che il chirurgo cerca durante l'intervento", "Quando si rompe il legamento crociato anteriore, a volte si lesiona anche l'attacco posteriore del menisco laterale. Una revisione del 2026 spiega che la risonanza non sempre la mostra e che il chirurgo la verifica durante l'artroscopia; quando è instabile, di solito si ripara nello stesso intervento.", "Nota rassicurante: è una lesione nota e trattabile; che cosa fare nel proprio ginocchio lo decide il chirurgo durante l'intervento."], "kw": "menisco laterale, radice del menisco, crociato anteriore, artroscopia del ginocchio"}, "5": {"prof": ["PRP, BMAC e tessuto adiposo nella sutura meniscale: nessuna superiorità clinica costante sulla sola sutura", "Revisione narrativa (KSSTA, 2026; solo abstract): PRP il più studiato, in genere senza differenze su VAS, IKDC, KOOS o Lysholm rispetto alla sola sutura; BMAC con più guarigione del PRP in alcuni studi preclinici e pochi dati clinici; MFAT solo in serie di casi nel degenerativo. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.", "Nota critica: revisione non sistematica, lesioni traumatiche e degenerative mescolate; l'unico dato numerico sulle rotture ripetute viene da un solo studio senza intervallo."], "mix": ["Plasma ricco di piastrine e cellule nella sutura del menisco: per ora nessun vantaggio sicuro", "Una revisione tedesca del 2026 ha raccolto gli studi su tre preparati biologici usati insieme alla sutura del menisco: il plasma ricco di piastrine, il concentrato di midollo osseo e il tessuto adiposo microframmentato. Il primo è il più studiato e in genere non migliora i punteggi rispetto alla sola sutura; per gli altri due i dati sull'uomo sono pochi.", "Nota sul limite: gli studi sono diversi fra loro per tipo di lesione e di tecnica, e la revisione non è sistematica."], "paz": ["Sutura del menisco e preparati biologici: che cosa sappiamo oggi", "Durante la sutura del menisco si possono aggiungere preparati ricavati dal sangue o dal grasso del paziente. Una revisione del 2026 dice che, per ora, non hanno mostrato un vantaggio costante rispetto alla sola sutura, che resta il cuore del trattamento.", "Nota rassicurante: la sutura del menisco funziona anche senza questi preparati; se aggiungerli si valuta caso per caso con il chirurgo."], "kw": "sutura del menisco, PRP ginocchio, cellule staminali menisco, lesione meniscale"}, "6": {"prof": ["Torsione tibiale alla TC: quattro metodi danno medie distanti fino a 13 gradi, con affidabilità eccellente", "Studio retrospettivo comparativo (KSSTA, 2026; solo abstract): 20 TC, tre osservatori; transmalleolare 34,1° (DS 8,6°), caviglia 31,2° (DS 8,8°), Jend 44,2° (DS 9,8°), Waidelich 34,9° (DS 9,0°), tutte diverse (p < 0,05); ICC > 0,89 per tutte.", "Nota critica: campione piccolo e nessun esito clinico; il dato vale per la lettura del referto, non per una soglia chirurgica."], "mix": ["Misurare la torsione della tibia: il risultato cambia con il metodo, e il referto deve dirlo", "Uno studio di Innsbruck ha misurato la torsione della tibia su 20 TAC con quattro metodi diversi: le medie vanno da 31 a 44 gradi, pur con misure molto ripetibili fra un osservatore e l'altro. Lo stesso ginocchio può quindi sembrare normale o fuori norma a seconda del metodo usato.", "Nota sul limite: le TAC sono poche e lo studio non dice quale metodo preveda meglio il risultato di un intervento."], "paz": ["Torsione della gamba alla TAC: perché è importante sapere come è stata misurata", "Nei problemi di instabilità della rotula a volte si misura la rotazione della tibia con una TAC. Uno studio del 2026 mostra che quattro metodi di misura danno valori diversi sullo stesso paziente, per cui il valore va sempre letto insieme al metodo.", "Nota rassicurante: le misure sono ripetibili e affidabili; il chirurgo le interpreta conoscendo il metodo usato."], "kw": "torsione tibiale, instabilità rotulea, TAC del ginocchio, osteotomia derotativa"}, "7": {"prof": ["Protesi robotica: tensore e stress manuale concordano sulla lassità solo a certi angoli, meno nel laterale", "Studio di misura intraoperatoria (Arthroplasty, 2026; solo abstract): 55 protesi bi-crociato stabilizzate; medialmente nessuna differenza fra stress manuale e 80 N a 10° e 30°, lateralmente lassità manuale maggiore a 30° e 60°; variabilità interosservatore più alta nel laterale. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.", "Nota critica: nessun esito clinico, robot non nominato e impianto bi-crociato stabilizzato; l'assenza di differenza su 55 ginocchia non è equivalenza."], "mix": ["Protesi con il robot: misurare la tensione dei legamenti a mano o con uno strumento non dà sempre lo stesso risultato", "Uno studio giapponese su 55 protesi di ginocchio eseguite con il robot ha confrontato la lassità dei legamenti misurata con uno strumento a forza controllata e con la manovra manuale del chirurgo. Le due misure concordano in alcune posizioni, ma sul lato esterno, a ginocchio piegato, la manovra manuale dà valori più ampi e varia di più fra un operatore e l'altro.", "Nota sul limite: lo studio non riporta i risultati clinici, quindi non dice quale misura porti a una protesi più stabile."], "paz": ["Protesi con il robot: come il chirurgo controlla l'equilibrio dei legamenti", "Durante una protesi con il robot il chirurgo verifica la tensione dei legamenti del ginocchio, a mano o con uno strumento dedicato. Uno studio giapponese su 55 protesi mostra che le due misure concordano in molte posizioni e differiscono in altre, soprattutto sul lato esterno a ginocchio piegato.", "Nota rassicurante: queste misure servono al chirurgo per affinare l'equilibrio della protesi durante l'intervento; lo studio non riguarda i risultati per il paziente."], "kw": "protesi robotica, protesi di ginocchio, bilanciamento legamentoso, chirurgia robotica del ginocchio"}};
var ARTICLES=[{n:1,mono:'m-gray',dot:'green',sec:'res',j:'Osteoarthritis Cartilage',h:'Protesi di ginocchio in età lavorativa: un programma digitale personalizzato anticipa di 23 giorni il ritorno alle attività scelte',v:'Studio randomizzato multicentrico in singolo cieco (11 centri olandesi, Amsterdam UMC): 287 pazienti in età lavorativa candidati a protesi totale o monocompartimentale. Tempo mediano alla ripresa delle attività scelte 52 giorni [32-84] con il programma iRecover contro 75 [36-137] con le cure abituali; hazard ratio 1,6 (1,3-2,0).',ax:'Straat, Coenen, Maarleveld, Huirne, Kerkhoffs, Anema, Kuijer; Amsterdam',date:'nov 2026',meta:'RCT multicentrico, 287 pazienti, livello alto, solo abstract',pmid:'43008926',doi:'10.1016/j.joca.2026.10.020',journal:'Osteoarthritis and cartilage',authors:'A Carlien Straat, Pieter Coenen, Jantine M Maarleveld, Judith A F Huirne, Gino M M J Kerkhoffs, Johannes R Anema, P Paul F M Kuijer, ',design:'Studio randomizzato controllato multicentrico in singolo cieco, 11 centri olandesi, ottobre 2020-gennaio 2023 (registro CCMO NL67692.029.18). Intervento: programma eHealth personalizzato «iRecover» con sensore di attività e consigli sul ritorno alle attività scelte dal paziente, un colloquio con un case manager e goal attainment scaling. Controllo: cure abituali, che comprendevano già una componente eHealth. Esito primario: tempo dall\'intervento alla ripresa delle attività scelte, misurato con il PROMIS-PF; modelli di Cox. Livello alto (RCT multicentrico), con il limite di un intervento comportamentale non mascherabile al paziente.',pop:'287 pazienti in età lavorativa in lista per protesi totale o monocompartimentale primaria, occupati almeno 8 ore a settimana e intenzionati a tornare al lavoro: 145 nell\'intervento (età 58 anni, donne 54%) e 142 nel controllo (59 anni, donne 51%). Ripartizione fra totale e monocompartimentale: non riportata nell\'abstract.',results:'Tempo mediano alla ripresa delle attività scelte: 52 giorni [32-84] con l\'intervento contro 75 [36-137] con le cure abituali (il tipo di intervallo fra parentesi non è specificato nell\'abstract). Hazard ratio 1,6 (1,3-2,0) a favore dell\'intervento. Ritorno al lavoro, sport, complicanze e punteggi del ginocchio: non riportati nell\'abstract.',concl:'Gli autori: rispetto alle cure abituali, il programma eHealth personalizzato riduce di una mediana di 23 giorni il tempo per tornare alle attività quotidiane scelte dal paziente.',limits:'Intervento comportamentale: il paziente non è in cieco e l\'esito è riferito, quindi aspettative e attenzione ricevuta pesano sul risultato · Il pacchetto unisce sensore, consigli, case manager e obiettivi: non dice quale componente produca l\'effetto · Popolazione selezionata (occupata e motivata) e quota di monocompartimentali non riportata · Esiti secondari e sicurezza non nell\'abstract',perte:'Verde: riguarda i tuoi pazienti di protesi totale e monocompartimentale ancora al lavoro. Il dato solido è che una guida strutturata e personalizzata sul ritorno alle attività accorcia i tempi di circa tre settimane; il programma è olandese e la sua trasferibilità non è nota. Cosa fare: nel colloquio pre-operatorio fissa con il paziente due o tre attività obiettivo con una data attesa, invece di un generico «qualche mese».'},
{n:2,mono:'m-gray',dot:'green',sec:'res',j:'Am J Sports Med',h:'Allotrapianto osteocondrale: l\'asse preoperatorio non predice esiti né reinterventi, ma i più deviati erano già stati riallineati',v:'Serie di casi di livello IV (Midwest Orthopaedics at Rush; 2005-2023, almeno 2 anni): 66 pazienti, nessuna misura di asse (HKA, LDFA, MPTA, JLCA) associata a MCID, PASS o SCB né ai reinterventi (p > 0,05). Reinterventi 37,9%, sopravvivenza dell\'innesto 93,9%. Con HKA oltre 5°, 13 su 16 avevano un riallineamento associato.',ax:'Sardesai, Ackermann, Vega … Yanke, Chahla, Cole; Rush, Chicago',date:'nov 2026',meta:'serie di casi, 66 pazienti, livello basso, solo abstract',pmid:'43006815',doi:'10.1177/03635465261500856',journal:'The American journal of sports medicine',authors:'Krish S Sardesai, Jakob Ackermann, Tomas Vega, Kyle N Kunze, Jason E Jesse, Samuel Alfonsi, Brian E Caplan, Jacob T Morgan, Lee R Friedman, Ron Gilat, Adam Yanke, Jorge Chahla, Brian J Cole',design:'Serie di casi retrospettiva (livello IV) di allotrapianti osteocondrali del ginocchio 2005-2023, con o senza riallineamento concomitante, controllo minimo di 2 anni. Asse su radiografie in carico dell\'arto intero (HKA, LDFA, MPTA, JLCA). Regressione logistica multivariata per esiti clinicamente significativi (MCID, SCB, PASS su IKDC e KOOS) e reinterventi; fallimenti e protesi solo descrittivi per i pochi eventi.',pop:'66 pazienti, età media 34,1 ± 11,5 anni, IMC 27,8 ± 4,8, donne 50%. Asse medio: HKA 1,8° ± 4,0°, LDFA 86,8° ± 2,3°, MPTA 86,3° ± 2,3°, JLCA 1,7° ± 1,0°. Sede dei difetti e numero totale di riallineamenti: non riportati nell\'abstract.',results:'Nessuna misura di asse associata a MCID, PASS o SCB né al reintervento per qualsiasi causa (p > 0,05). Reinterventi 25 su 66 (37,9%); sopravvivenza dell\'innesto 93,9%, con 4 fallimenti e 3 conversioni a protesi. Sottoanalisi esplorativa con HKA oltre 5° in varo o valgo (16 pazienti, 13 riallineati) contro gli altri: reinterventi 43,8% contro 36,0% (p = 0,768), fallimenti 6,3% contro 6,0% (p > 0,999).',concl:'Gli autori: in una coorte piccola ed eterogenea l\'asse preoperatorio non è associato agli esiti; i dati generano ipotesi, non escludono un effetto dell\'asse né definiscono una soglia per riallineare, perché quasi tutti i malallineati gravi erano stati corretti.',limits:'Confondimento per indicazione: chi era deviato è stato quasi sempre riallineato, quindi lo studio misura l\'asse corretto, non quello lasciato · 66 pazienti e 4 fallimenti: nessuna potenza sulla sopravvivenza dell\'innesto · Allotrapianto, non AMIC né minced cartilage: trasferibilità limitata alla tua casistica cartilaginea',perte:'Verde: tocca il binomio cartilagine-osteotomia che pratichi. Non autorizza a trascurare l\'asse: dice che, quando l\'asse viene corretto insieme al trapianto, i deviati non vanno peggio. Cosa fare: nessun cambio; continua a correggere l\'asse sopra la soglia che già usi, perché questo studio non può dire che cosa succede se non lo fai.'},
{n:3,mono:'m-gray',dot:'green',sec:'res',j:'Bone Jt Open',h:'Infiltrazioni nel ginocchio fra 40 e 60 anni: ogni iniezione in più si associa a un rischio di protesi più alto del 12%',v:'Coorte di popolazione (Olmsted County, Mayo Clinic; prime iniezioni 2000-2010): 1.897 pazienti, 2.336 ginocchia, 8.600 iniezioni di corticosteroide o acido ialuronico; protesi nel 39,3%. Per iniezione HR 1,12 (IC 95% 1,08-1,17), aggiustato per età, IMC e grado KL. Nell\'artrosi iniziale (KL 0-1) corticosteroide HR 1,27 (IC 95% 1,17-1,37).',ax:'Panos, Twohey, Johnson … Hevesi, Krych … Nagelli; Mayo Clinic, Rochester',date:'nov 2026',meta:'coorte di popolazione, 1.897 pazienti, livello medio, solo abstract',pmid:'43008781',doi:'10.1302/2633-1462.711.BJO-2026-0107.R1',journal:'Bone & joint open',authors:'Joseph A Panos, Eric E Twohey, Shelby E Johnson, Brennan J Boettcher, Parker Scott, Mario Hevesi, Aaron J Krych, Christopher H Evans, Jacob L Sellon, Christopher V Nagelli',design:'Coorte retrospettiva di popolazione (Olmsted County, Minnesota) su pazienti di 40-60 anni alla prima infiltrazione intra-articolare di corticosteroide e/o acido ialuronico fra il 2000 e il 2010. Esito primario: protesi in funzione del numero di iniezioni; regressione di Cox aggiustata per età, IMC e grado di Kellgren-Lawrence alla prima iniezione. Livello medio (coorte con confronto interno).',pop:'1.897 pazienti, 2.336 ginocchia, 8.600 iniezioni (5.786 corticosteroide, 2.814 acido ialuronico); età media 51,9 ± 5,5 anni, donne 64,9%, IMC medio 34,8 ± 8,0. Durata del controllo: non riportata nell\'abstract.',results:'Protesi in 917 ginocchia (39,3%). Numero di iniezioni: HR 1,12 per iniezione (IC 95% 1,08-1,17). Artrosi iniziale (KL 0-1): corticosteroide HR 1,27 (IC 95% 1,17-1,37), acido ialuronico HR 1,12 (IC 95% 1,06-1,19). Confronto diretto fra i due farmaci con il suo intervallo: non riportato nell\'abstract.',concl:'Gli autori: ogni infiltrazione si associa a un aumento del 12% della probabilità di protesi; nell\'artrosi iniziale il corticosteroide si associa a un aumento del 27%.',limits:'Confondimento per indicazione: chi riceve più iniezioni ha più sintomi, e i sintomi portano alla protesi; l\'aggiustamento per grado KL non lo cattura · Dolore, funzione e attività non sono fra le covariate · Popolazione americana con IMC medio 34,8: trasferibilità limitata ai tuoi pazienti',perte:'Verde: tocca le infiltrazioni nel paziente giovane con artrosi che vedi in ambulatorio. È un\'associazione, non la prova che l\'iniezione acceleri l\'artrosi. Cosa fare: nessun cambio di indicazione; per chi chiede cortisone ripetuto con artrosi iniziale, è un motivo in più per contare le iniezioni e ridiscutere il percorso quando si accumulano.'},
{n:4,mono:'m-gray',dot:'green',sec:'res',j:'J ISAKOS',h:'Radice posteriore del menisco laterale con LCA rotto: la riparazione migliora i punteggi, ma un beneficio sull\'innesto non è dimostrato',v:'Revisione narrativa «current concepts» (Teheran): frequenza nelle ricostruzioni primarie fra 7,1% e 12,2%, fino al 40,7% in revisioni selezionate, con definizioni diverse. Associazioni ricorrenti: trauma da contatto, lesione meniscale mediale, slope tibiale laterale aumentato. Le classificazioni (LaPrade, Forkel-Petersen, LMORT) sono descrittive, non algoritmi validati.',ax:'Shirouei, Ayati Firoozabadi, Mortazavi; Teheran',date:'nov 2026',meta:'revisione narrativa, livello basso, solo abstract',pmid:'43008370',doi:'10.1016/j.jisako.2026.101243',journal:'Journal of ISAKOS : joint disorders & orthopaedic sports medicine',authors:'Sepehr Shirouei, Mohammad Ayati Firoozabadi, Seyed Mohammad Javad Mortazavi',design:'Revisione narrativa di concetti attuali su incidenza, fattori di rischio, biomeccanica, diagnosi, classificazione, trattamento ed esiti delle lesioni della radice posteriore del menisco laterale nel ginocchio con lesione del LCA, distinte dalle lesioni radiali oblique del corno posteriore (LMORT). Metodo di ricerca: non riportato nell\'abstract. Livello basso.',pop:'Nessuna popolazione propria: studi riassunti con definizioni e modalità di accertamento diverse. Numero di studi: non riportato nell\'abstract.',results:'Frequenza: 7,1%, 10,0% e 12,2% in coorti di ricostruzione primaria; 6,6% in una coorte mista; 20,5% e 40,7% in coorti di revisione selezionate. Singoli segni RM con sensibilità limitata. Riparazione (sull\'impronta o lato-lato) con la ricostruzione associata a punteggi riferiti migliori e ad alte proporzioni di guarigione completa o parziale in serie selezionate. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: le lesioni stabili selezionate si possono osservare, quelle instabili riparabili si riparano; un miglioramento della sopravvivenza dell\'innesto non è dimostrato, e definizioni eterogenee ed evidenza di basso livello limitano le conclusioni su cartilagine e trattamento ottimale.',limits:'Revisione narrativa senza metodo sistematico dichiarato: selezione delle fonti non verificabile · Frequenze non confrontabili fra loro, come ammettono gli autori · Nessun confronto riparazione contro osservazione con esiti duri',perte:'Verde: tocca la radice meniscale e la ricostruzione del LCA che fai, sul versante laterale. Cosa fare: in ogni ricostruzione sonda la radice posteriore laterale in artroscopia, perché la RM da sola la perde; e non presentare la riparazione come protezione dell\'innesto, perché non è dimostrata.'},
{n:5,mono:'m-gray',dot:'green',sec:'res',j:'Knee Surg Sports Traumatol Arthrosc',h:'PRP, concentrato midollare e tessuto adiposo nella sutura meniscale: nessuna superiorità clinica costante sulla sola sutura',v:'Revisione narrativa (König-Ludwig-Haus, Würzburg): il PRP è il più studiato, con risultati eterogenei e in genere senza differenze sui punteggi rispetto alla sola sutura. Il concentrato midollare guarisce meglio del PRP in alcuni modelli animali, con pochi dati clinici; il tessuto adiposo microframmentato ha solo serie di casi nel degenerativo. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',ax:'Pattappa, Müller, Zellner, Docheva, Angele; Würzburg',date:'nov 2026',meta:'revisione narrativa, livello basso, solo abstract',pmid:'43007302',doi:'10.1002/ksa.70655',journal:'Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA',authors:'Girish Pattappa, Nicholas Müller, Johannes Zellner, Denitsa Docheva, Peter Angele',design:'Revisione narrativa delle evidenze precliniche e cliniche su plasma ricco di piastrine (PRP), concentrato di aspirato midollare (BMAC) e tessuto adiposo microframmentato (MFAT) come complemento al trattamento delle lesioni meniscali, con annotazione di approccio, tipo di lesione, guarigione ed esiti riferiti dal paziente. Livello dichiarato N/A; qui basso.',pop:'Nessuna popolazione propria; numero di studi inclusi non riportato nell\'abstract.',results:'PRP: nessuna differenza significativa costante su VAS, IKDC, KOOS o Lysholm rispetto alla sola sutura; in un solo studio rotture ripetute 14,6% con PRP contro 17% senza (intervallo non riportato). BMAC: guarigione maggiore del PRP in alcuni studi preclinici, evidenza clinica comparativa limitata. MFAT: solo serie di casi nel degenerativo con artrosi, nessuno studio animale. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: le evidenze attuali non mostrano una superiorità clinica costante di PRP, BMAC o MFAT sui trattamenti meniscali standard; il PRP ha la base più ampia ma eterogenea.',limits:'Revisione narrativa: selezione delle fonti non sistematica · L\'unico numero viene da un solo studio, senza intervallo · Lesioni traumatiche e degenerative mescolate',perte:'Verde: tocca la sutura meniscale e l\'asse delle terapie biologiche. Cosa fare: nessun cambio; se aggiungi un ortobiologico alla sutura, presentalo al paziente come scelta non dimostrata, non come garanzia di guarigione.'},
{n:6,mono:'m-gray',dot:'green',sec:'res',j:'Knee Surg Sports Traumatol Arthrosc',h:'Torsione tibiale alla TC: quattro metodi danno valori medi distanti fino a 13 gradi, e il referto deve dire quale',v:'Studio retrospettivo comparativo (Innsbruck; livello III): 20 TC di adulti, tre osservatori. Torsione media 34,1° (DS 8,6°) con l\'asse transmalleolare, 31,2° (DS 8,8°) con l\'asse della caviglia, 44,2° (DS 9,8°) con Jend, 34,9° (DS 9,0°) con Waidelich; tutte diverse (p < 0,05). Affidabilità eccellente per tutte (ICC > 0,89).',ax:'Benefelds, Juen, Kaiser, Lindtner, Kummann, Mayr; Innsbruck',date:'nov 2026',meta:'studio retrospettivo di misura, 20 TC, livello basso, solo abstract',pmid:'43002783',doi:'10.1002/ksa.70672',journal:'Knee surgery, sports traumatology, arthroscopy : official journal of the ESSKA',authors:'Marcis Benefelds, Ulrich Juen, Peter Kaiser, Richard Lindtner, Moritz Kummann, Raul Mayr',design:'Studio retrospettivo comparativo di misura (livello III dichiarato) su TC: torsione tibiale con due assi prossimali (tangente al piatto tibiale posteriore e asse della tuberosità) e quattro distali (transmalleolare, caviglia, Jend, Waidelich). Tre osservatori indipendenti, misure ripetute dopo 8-12 settimane; ANOVA per misure ripetute con correzione di Bonferroni e coefficienti di correlazione intraclasse. Livello basso secondo la rubrica (nessun esito clinico).',pop:'TC di 20 pazienti adulti; indicazione, età e sesso: non riportati nell\'abstract.',results:'Tutte le tecniche differiscono (p < 0,05). Torsione media: transmalleolare 34,1° (DS 8,6°), caviglia 31,2° (DS 8,8°), Jend 44,2° (DS 9,8°), Waidelich 34,9° (DS 9,0°). Sopra la tuberosità 26° (DS 6,7°); sotto la tuberosità da 5,1° (DS 8,9°) a 18,1° (DS 10,4°) secondo l\'asse distale. Affidabilità intra- e interosservatore eccellente (ICC > 0,89).',concl:'Gli autori: i valori dipendono fortemente dalla tecnica; servono valori normativi specifici, il referto deve indicare la tecnica usata, e chi pianifica un\'osteotomia derotativa deve tenerne conto.',limits:'20 TC: campione piccolo per valori normativi · Nessun esito clinico né soglia chirurgica per tecnica · Popolazione non descritta nell\'abstract',perte:'Verde: tocca l\'instabilità rotulea e la MPFL, quando valuti la torsione. Cosa fare: quando chiedi una TC torsionale, esigi che il referto indichi il metodo e confronta il valore solo con soglie misurate con lo stesso metodo; lo stesso paziente può sembrare normale o patologico solo per l\'asse distale scelto.'},
{n:7,mono:'m-gray',dot:'green',sec:'res',j:'Arthroplasty',h:'Protesi robotica: la lassità misurata con il tensore e quella con lo stress manuale coincidono solo a certi angoli',v:'Studio di misura intraoperatoria (Saitama, Giappone): 55 protesi bi-crociato stabilizzate con sistema robotico, tensore a 60 e 80 N contro stress manuale. Medialmente nessuna differenza con 80 N a 10° e 30°; lateralmente lo stress manuale dà più lassità a 30° e 60°. Variabilità fra osservatori maggiore nel laterale. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',ax:'Inui, Nakamura, Takei, Uchida, Satou, Yamashita, Matsumoto; Saitama',date:'nov 2026',meta:'studio di misura intraoperatoria, 55 protesi, livello basso, solo abstract',pmid:'43004409',doi:'10.1186/s42836-026-00449-9',journal:'Arthroplasty (London, England)',authors:'Hiroshi Inui, Haruhiko Nakamura, Ryota Takei, Masaki Uchida, Kei Satou, Tetsu Yamashita, Risa Matsumoto',design:'Studio di misura intraoperatoria su protesi totali bi-crociato stabilizzate eseguite con un sistema robotico (non nominato nell\'abstract). Lassità mediale e laterale con tensore a forza controllata a 60 e 80 N a 10°, 30°, 60° e 90° e con stress manuale in varo-valgo registrato dal robot; ogni misura ripetuta in modo indipendente dal chirurgo senior e da un assistente. Livello basso (nessun esito clinico).',pop:'55 protesi totali bi-crociato stabilizzate; età, diagnosi e deformità: non riportate nell\'abstract.',results:'Medialmente: nessuna differenza significativa fra stress manuale e 80 N a 10° e 30°; a 90° nessuna differenza fra stress manuale e 60 N. Lateralmente: nessuna differenza con 80 N a 10° e 90°, lassità manuale significativamente maggiore a 30° e 60°. Variabilità interosservatore più alta nel laterale e ai gradi di flessione maggiori. Dimensioni dell\'effetto e intervalli di confidenza non riportati nell\'abstract.',concl:'Gli autori: la concordanza fra stress manuale e tensore dipende dal compartimento e dall\'angolo; il laterale è il più variabile, e la valutazione della lassità durante la protesi robotica va standardizzata.',limits:'Nessun esito clinico: non dice quale misura predica il risultato · Impianto bi-crociato stabilizzato e robot non nominato: trasferibilità limitata al tuo VELYS · «Nessuna differenza significativa» su 55 ginocchia non è equivalenza',perte:'Verde: tocca la valutazione dei gap con il VELYS, che si basa sullo stress manuale. Cosa fare: nel compartimento laterale fra 30° e 60° di flessione considera la lassità misurata a mano la meno riproducibile, e ripeti la manovra prima di decidere un rilascio o un cambio d\'inserto.'}];
var SUGGQ=[{"k": "kol", "n": "Christoph Kittl (Università di Münster, Germania)", "w": "Germania: ultimo autore dello studio sul carico del LCA con varismo e angolo posterolaterale (PMID 42897444; nome e afferenza letti nei metadati PubMed), già comparso in elenchi di coautori nello storico. Corrispondenza tecnica con l'osteotomia correttiva e la protezione del LCA con la ricostruzione dell'angolo posterolaterale, cioè gli ambiti osteotomia e slope che esegui. Sostituisce Daniel B. F. Saris (nessun segnale dell'utente arrivato per farla ruotare)."}];
var BRIEF_TEXT="Mercoledì undici novembre, sette lavori, nessuna scheda rossa. Nessun richiamo di dispositivi nuovo che ti riguardi, nessuna ritrattazione di lavori che abbiamo citato e nessun citante nuovo sui tuoi verdetti passati; il raccoglitore è quello di ieri mattina e tutte le fonti hanno risposto. Il lavoro del giorno è uno studio randomizzato olandese in undici centri, duecentottantasette pazienti in età lavorativa operati di protesi totale o monocompartimentale: con un programma digitale personalizzato, con sensore di attività, case manager e obiettivi scelti dal paziente, le attività scelte riprendono in una mediana di cinquantadue giorni contro settantacinque, hazard ratio uno virgola sei, intervallo da uno virgola tre a due. Il paziente però non è in cieco e lo studio non dice quale componente conti; per te il principio pratico è fissare obiettivi e date nel colloquio pre-operatorio. Seconda scheda, l'allotrapianto osteocondrale a Chicago: in sessantasei pazienti l'asse preoperatorio non predice esiti né reinterventi, ma tredici dei sedici più deviati erano già stati riallineati, quindi lo studio è muto sull'asse lasciato. Terza, la Mayo Clinic sulle infiltrazioni fra quaranta e sessant'anni: ogni iniezione si associa a un rischio di protesi più alto del dodici per cento, il cortisone nell'artrosi iniziale del ventisette, con un forte confondimento per indicazione. Quarta e quinta, il menisco: una revisione narrativa sulla radice posteriore laterale nel ginocchio con crociato rotto, dove la riparazione migliora i punteggi ma non è dimostrato che protegga l'innesto, e una revisione di Würzburg secondo cui plasma ricco di piastrine, concentrato midollare e tessuto adiposo non sono costantemente superiori alla sola sutura. Sesta, Innsbruck: la torsione tibiale alla TC cambia fino a tredici gradi in media a seconda del metodo, e il referto deve dire quale. Settima, protesi robotica: lassità misurata con il tensore e con lo stress manuale concordano solo a certi angoli, meno nel compartimento laterale. Nessuna tensione si sposta oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Mercoledì undici novembre, sette lavori, nessuna scheda rossa. Nessun richiamo nuovo che ti riguardi, nessuna ritrattazione e nessun citante nuovo sui tuoi verdetti passati."}, {"chi": "B", "t": "Qual è il lavoro del giorno?"}, {"chi": "A", "t": "Uno studio randomizzato olandese in undici centri: duecentottantasette pazienti in età lavorativa, protesi totale o monocompartimentale. Con un programma digitale personalizzato riprendono le attività scelte in una mediana di cinquantadue giorni contro settantacinque."}, {"chi": "B", "t": "Ed è un effetto solido?"}, {"chi": "A", "t": "Hazard ratio uno virgola sei, intervallo da uno virgola tre a due. Ma il paziente non è in cieco, e lo studio non dice quale parte del programma conti."}, {"chi": "B", "t": "Quindi per i miei pazienti di protesi ancora al lavoro?"}, {"chi": "A", "t": "Il principio è trasferibile: nel colloquio pre-operatorio fissa due o tre attività obiettivo con una data attesa."}, {"chi": "B", "t": "E la cartilagine?"}, {"chi": "A", "t": "Allotrapianto osteocondrale a Chicago, sessantasei pazienti: l'asse non predice esiti né reinterventi, ma tredici dei sedici più deviati erano stati riallineati. Muto sull'asse lasciato."}, {"chi": "B", "t": "Le infiltrazioni della Mayo?"}, {"chi": "A", "t": "Ogni iniezione si associa a un rischio di protesi più alto del dodici per cento. È un'associazione con un forte confondimento per indicazione, non una prova di danno."}, {"chi": "B", "t": "Sul menisco?"}, {"chi": "A", "t": "Due revisioni narrative. Sulla radice posteriore laterale, ripararla migliora i punteggi ma non è dimostrato che protegga l'innesto. Gli ortobiologici non sono costantemente superiori alla sola sutura."}, {"chi": "B", "t": "E le ultime due?"}, {"chi": "A", "t": "La torsione tibiale alla TC cambia fino a tredici gradi a seconda del metodo, quindi il referto deve dire quale. E nella protesi robotica tensore e stress manuale concordano solo a certi angoli, meno nel laterale."}, {"chi": "B", "t": "Nessuna tensione si sposta?"}, {"chi": "A", "t": "No: giornata di principi pratici più che di svolte."}];
